-- GUIDs that belong to Unity's own packages (URP, uGUI, Timeline and the rest), so a
-- reference to one can name the package instead of showing as missing. A .unitypackage
-- or a project's Assets/ points at these files but never contains them.
--
-- Rows come from two places: the seed below (version NULL), taken from the Package
-- Manager caches of real projects and limited to GUIDs Asset Store content actually
-- references, and each scanned project's Library/PackageCache, which adds the rest.

CREATE TABLE unity_known_guids (
  guid TEXT PRIMARY KEY,
  package TEXT NOT NULL,
  -- NULL for seed rows; a learned row records the package version it was read from.
  version TEXT,
  rel_path TEXT NOT NULL
) WITHOUT ROWID;

-- package@version folders already read from some project's PackageCache.
CREATE TABLE unity_package_cache_seen (
  package TEXT NOT NULL,
  version TEXT NOT NULL,
  PRIMARY KEY (package, version)
) WITHOUT ROWID;

